import json,pathlib,chess,chess.pgn,io,hashlib,datetime,re,gzip
root=pathlib.Path('/Users/johnweathers/.codex/worktrees/chess-adversarial-assessment/mShogi')
historical=json.load(open(root/'docs/m5/evidence/msh154/gameplay/msh-gameplay-panel.json'))
start=chess.STARTING_FEN
panel=[]
def hist(idx,id,primary,tags,role,preferred,avoid,why):
 x=historical[idx];b=chess.Board()
 for u in x['history']:b.push_uci(u)
 assert b.fen()==x['fen']
 z={'id':id,'kind':'historical','primary_category':primary,'secondary_categories':tags,'sample_role':role,'fresh':False,'fen':start,'history':x['history'],'expected_root_fen':x['fen'],'source':{'path':'docs/m5/evidence/msh154/gameplay/msh-gameplay-panel.json','pair':x['pair'],'game':x['game'],'ply':x['ply']},'history_policy':'Complete original game history from standard start, including every reversible move; no FEN reset.','expectation':{'type':'preserved finite reference assessment; neither rules proof nor unique-optimality claim','preferred_moves_nonexhaustive':preferred,'known_disfavored_moves':avoid,'unlisted_move_policy':'Unresolved unless an approved common-condition reference check or exact continuation establishes quality; do not mark wrong solely for absence from preferred list.','rationale':why},'time_ms':1000}
 panel.append(z)
hist(0,'historical-22Nf5','tactical',['positional','coordination'],'prior weakness',['d3f5','a1b1','h2h3'],['e3f5'],'22.Nf5 is a tactical/coordination weakness anchor with queen liquidation and loose-pawn consequences, not a pure forced-mate puzzle. Preserved bound-safe 2m-node reference disfavors Nf5 (-290cp) against Bf5 (+22cp), Rab1 (+25cp at500k), h3 (-25cp at500k). Candidate set is nonexhaustive and depths/limits differ; no cross-search cp proof.')
# Fresh attacking holdout: full source-game history, not API synthetic fullmove=1.
j=json.load(open('/tmp/msh155-puzzleSfkRC.json'));g=chess.pgn.read_game(io.StringIO(j['game']['pgn']));history=[m.uci() for m in g.mainline_moves()];b=g.end().board();proof=next(x for x in json.load(open('/tmp/msh155-mate-proof.json'))['results'] if x['id']=='SfkRC')
assert b.fen()==proof['root_fen']
panel.append({'id':'fresh-SfkRC','kind':'puzzle','primary_category':'tactical','secondary_categories':['sacrifice','attraction','pin'],'sample_role':'fresh attacking holdout','fresh':True,'fen':start,'history':history,'history_policy':'Full published source-game history from standard start, ending at the puzzle root. API puzzle.fen supplies synthetic fullmove1; this input uses actual fullmove27 from PGN.','expected_root_fen':b.fen(),'source':{'url':'https://lichess.org/api/puzzle/SfkRC','puzzle_url':'https://lichess.org/training/SfkRC','raw_file':'/tmp/msh155-puzzleSfkRC.json','game_id':j['game']['id'],'published_rating_at_retrieval':j['puzzle']['rating']},'expected_line':j['puzzle']['solution'],'expectation':{'type':'exact bounded forced-mate proof plus published solution','mate_within_plies':5,'accepted_moves':['b6f2'],'unique_within_bound':True,'all_legal_roots_enumerated':29,'proof_file':'/tmp/msh155-mate-proof.json','grading':'Pass only b6f2 for finding mate within5plies; this does not prove every other move loses or lacks a longer mate.'},'time_ms':1000})
hist(2,'historical-24h4','positional',['tactical','king_safety'],'successful game control',['h3h4'],['g2g3'],'Historical24.h4 is supported by unrestricted500k reference(+200cp), played(+176cp), while the proposed g3 alternative is strongly disfavored(-575cp). The game was won; this control tests preservation of useful pawn/king coordination, not proof that h4 is uniquely best.')
line=pathlib.Path('/tmp/msh155-sts-v3.epd').read_text().splitlines()[3];pos=chess.Board();ops=pos.set_epd(line);assert ops['id']=='STS(v1.0) Undermine.004';moves=re.search('c9 "([^"]+)"',line).group(1).split();points=list(map(int,re.search('c8 "([^"]+)"',line).group(1).split()));scores=dict(zip(moves,points));assert scores=={'b4b5':10,'g2g3':4,'f3g5':4,'d2e3':4}
for u in moves:assert chess.Move.from_uci(u) in pos.legal_moves
panel.append({'id':'fresh-sts-undermine-004','kind':'strategic','primary_category':'positional','secondary_categories':['pawn_break','undermining'],'sample_role':'fresh positional holdout','fresh':True,'fen':pos.fen(),'history':[],'expected_root_fen':pos.fen(),'history_policy':'EPD-only independent root. No pre-root history available; halfmove0/fullmove1 are synthetic, not assertions about a source game. No repetition-history claims.','source':{'url':'https://raw.githubusercontent.com/fsmosca/STS-Rating/master/STS1-STS15_LAN_v3.epd','readme_url':'https://github.com/fsmosca/STS-Rating','raw_file':'/tmp/msh155-sts-v3.epd','line_1_based':4,'original_id':ops['id'],'raw_epd':line},'expectation':{'type':'published STS positional preference, soft benchmark only','preferred_moves_nonexhaustive':['b4b5'],'published_points':scores,'max_points':10,'grading':'Report published points only for listed moves. An unlisted move is unresolved, not a proven failure or0 unless independently reassessed. Published points are neither cp nor outcome probabilities.','rationale':'A queenside pawn lever probes planning distinct from the historical h4 control; no forced-mate claim and no contemporary engine answer informed selection.'},'time_ms':1000})
hist(3,'historical-23Rf6','defensive',['tactical','king_safety'],'prior weakness',['d6e4','a8d8'],['f8f6'],'23...Rf6 is the prior defensive/tactical weakness. Preserved bound-safe2m reference: Ne4=0cp, Rad8=-37cp, Rf6=-371cp. Later ...Rf6 at a different moment is not the same decision. Nonexhaustive preferences; no claim of exhaustive best defense.')
for n,id,cat,role,fen,good in [('reti','fresh-reti-draw','defensive','fresh defensive holdout','7K/8/k1P5/7p/8/8/8/8 w - - 0 1',['h8g7']),('dedrle','fresh-dedrle-win','endgame','fresh winning endgame holdout','8/8/5k2/8/p7/8/1PK5/8 w - - 0 1',['c2b1'])]:
 tb=json.load(open('/tmp/msh155-tb-'+n+'.json'));b=chess.Board(fen);assert set(m.uci() for m in b.legal_moves)==set(x['uci'] for x in tb['moves']);mapping={x['uci']:x['category'] for x in tb['moves']};inv={'win':'loss','loss':'win','draw':'draw','cursed-win':'blessed-loss','blessed-loss':'cursed-win'};rootmap={m:inv[v] for m,v in mapping.items()}
 assert [m for m,c in rootmap.items() if c==tb['category']]==good
 z={'id':id,'kind':'tablebase','primary_category':cat,'secondary_categories':['endgame','pawn_race','king_coordination'] if n=='reti' else ['pawn_endgame','zugzwang','king_coordination'],'sample_role':role,'fresh':True,'fen':fen,'history':[],'expected_root_fen':fen,'history_policy':'Independent study root; no pre-root history asserted. Supplied halfmove0/fullmove1 starts this benchmark state. No repetition-history claim. Tablebase50move-aware category at this reset only.','expected_category':tb['category'],'tb_moves':mapping,'tb_moves_perspective':'Child side to move, matching Lichess API raw category; invert win/loss to grade root side.','source':{'url':'https://tablebase.lichess.ovh/standard?fen='+__import__('urllib.parse',fromlist=['quote']).quote(fen,safe=''),'raw_file':'/tmp/msh155-tb-'+n+'.json','study_position_reproduction':'https://devonjuniorchess.co.uk/content/endgame-studies','study_name':'Réti draw' if n=='reti' else 'Dedrle1921 win'},'expectation':{'type':'complete exact tablebase legal-move WDL map','accepted_moves':good,'root_category':tb['category'],'root_side_categories':rootmap,'root_dtz':tb['dtz'],'grading':'Preserve exact root WDL category. API move categories are child-side; no use of finite cp. No cursed-win/blessed-loss categories occur in these responses. DTZ is distance to zeroing, not mate length.','oracle_legal_move_count':len(mapping)},'time_ms':1000}
 panel.append(z)
 # Insert historical rook-ending before fresh winning endgame to retain category order.
 if n=='reti':hist(10,'historical-34Rc5','endgame',['rook_ending','coordination'],'successful game control',['e2e3','e4e3','a5c5'],[],'Historical game was won and Rc5 retains a substantial finite-reference advantage(+341cp at2m), but Ke3(+474cp) and Re3(+375cp) are preferred by the preserved2m probe. This is a conversion control with known room for improvement, not proof Rc5 is optimal or the game is theoretically won.')
assert len(panel)==8
for z in panel:
 b=chess.Board(z['fen'])
 for u in z['history']:assert chess.Move.from_uci(u) in b.legal_moves;b.push_uci(u)
 assert b.is_valid() and b.fen()==z['expected_root_fen']
 for u in z['expectation'].get('accepted_moves',z['expectation'].get('preferred_moves_nonexhaustive',[])):assert chess.Move.from_uci(u) in b.legal_moves
json.dump(panel,open('/tmp/msh155-panel.json','w'),indent=2)
print('Frozen',datetime.datetime.now(datetime.timezone.utc).isoformat(),'sha256',hashlib.sha256(pathlib.Path('/tmp/msh155-panel.json').read_bytes()).hexdigest())
for z in panel:print(z['id'],z['primary_category'],z['fresh'],len(z['history']),z['expected_root_fen'])
